import {
  StyleProp,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
  ViewStyle,
} from "react-native";
import React from "react";
import CustomText from "../../myComponents/CustomText/CustomText";
import { color } from "../../const/color";
import moment from "moment";
import { roleHRM, statusColor, statusHRM } from "../../utils/hrmKeysMatchToBE";
import {
  shadowPrimaryColor,
  shadowSecondaryColor,
} from "../../const/globalStyle";
import SlideFadeIn from "../../utils/animations/SlideFadeIn";

interface TRowLeaveInAllList {
  containerStyle?: StyleProp<ViewStyle>;
  onPress?: () => void;
  item: {
    name: string;
    role: string;
    status: string;
    days: number;
    createdAt: string;
  };
  isAgent?: boolean;
}

const RowLeaveInAllList = ({
  containerStyle,
  onPress,
  item,
  isAgent,
}: TRowLeaveInAllList) => {
  const getStatusBorderColor = (status) => {
    const colors = {
      approved: "#48BB78",
      pending: "#ED8936",
      rejected: "#F56565",
    };
    return colors[status] || "#CBD5E0";
  };

  return (
    <TouchableOpacity
      onPress={onPress}
      style={[
        styles.card,
        { borderLeftColor: getStatusBorderColor(item?.status) },
        containerStyle,
      ]}
    >
      {!isAgent && (
        <View style={styles.contentContainer}>
          <View style={styles.mainInfo}>
            <SlideFadeIn>
              <CustomText style={styles.nameText}>{item?.name}</CustomText>
            </SlideFadeIn>
            <SlideFadeIn>
              <CustomText style={styles.roleText}>
                {roleHRM[item?.role]}
              </CustomText>
            </SlideFadeIn>
          </View>

          <View style={styles.detailsContainer}>
            <View style={styles.detailItem}>
              <SlideFadeIn>
                <CustomText style={styles.detailLabel}>Days</CustomText>
              </SlideFadeIn>

              <View style={styles.daysBadge}>
                <SlideFadeIn>
                  <CustomText style={styles.daysText}>{item?.days}</CustomText>
                </SlideFadeIn>
              </View>
            </View>

            <View style={styles.statusItem}>
              <View
                style={[
                  styles.statusBadge,
                  { backgroundColor: `${statusColor[item?.status]}20` },
                ]}
              >
                <SlideFadeIn>
                  <CustomText
                    style={[
                      styles.statusText,
                      { color: statusColor[item?.status] },
                    ]}
                  >
                    {statusHRM[item?.status]}
                  </CustomText>
                </SlideFadeIn>
              </View>
              <SlideFadeIn>
                <CustomText style={styles.dateText}>
                  {moment(item?.createdAt).format("DD/MM/YYYY") ?? "NA"}
                </CustomText>
              </SlideFadeIn>
            </View>
          </View>
        </View>
      )}
      {isAgent && (
        <View style={styles.contentContainer}>
          <View style={styles.daysSection}>
            <SlideFadeIn>
              <CustomText style={styles.daysText}>{item?.days}</CustomText>
            </SlideFadeIn>
            <SlideFadeIn>
              <CustomText style={styles.detailLabel}>Days</CustomText>
            </SlideFadeIn>
          </View>

          <View style={styles.mainInfo}>
            <SlideFadeIn>
              <CustomText style={styles.roleText}>
                {roleHRM[item?.role]}
              </CustomText>
            </SlideFadeIn>
          </View>

          <View style={styles.statusSection}>
            <View
              style={[
                styles.statusBadge,
                { backgroundColor: `${statusColor[item?.status]}20` },
              ]}
            >
              <SlideFadeIn>
                <CustomText
                  style={[
                    styles.statusText,
                    { color: statusColor[item?.status] },
                  ]}
                >
                  {statusHRM[item?.status]}
                </CustomText>
              </SlideFadeIn>
            </View>
            <SlideFadeIn>
              <CustomText style={styles.dateText}>
                {moment(item?.createdAt).format("DD/MM/YYYY") ?? "NA"}
              </CustomText>
            </SlideFadeIn>
          </View>
        </View>
      )}
    </TouchableOpacity>
  );
};

export default RowLeaveInAllList;

const styles = StyleSheet.create({
  card: {
    backgroundColor: "#FFFFFF",
    borderRadius: 16,
    padding: 16,
    marginHorizontal: 4,
    ...shadowPrimaryColor,
    borderLeftWidth: 4,
  },
  contentContainer: {
    flexDirection: "row",
    justifyContent: "space-between",
    alignItems: "center",
  },
  mainInfo: {
    flex: 1,
    gap: 4,
  },
  nameText: {
    fontSize: 16,
    fontWeight: "600",
    color: color.mainTxtColor,
  },
  roleText: {
    fontSize: 14,
    fontWeight: "400",
    color: color.strokeColor,
  },
  detailsContainer: {
    flexDirection: "row",
    alignItems: "center",
    gap: 16,
  },
  detailItem: {
    alignItems: "center",
    gap: 4,
  },
  daysSection: {
    alignItems: "center",
    gap: 4,
  },
  statusSection: {
    alignItems: "flex-end",
    gap: 4,
  },
  statusItem: {
    alignItems: "flex-end",
    gap: 4,
  },
  detailLabel: {
    fontSize: 12,
    fontWeight: "500",
    color: "#A0AEC0",
    textTransform: "uppercase",
  },
  daysBadge: {
    backgroundColor: "#4299E1",
    borderRadius: 12,
    paddingHorizontal: 8,
    paddingVertical: 2,
    minWidth: 30,
    alignItems: "center",
  },
  daysText: {
    fontSize: 14,
    fontWeight: "700",
    color: "#FFFFFF",
  },
  statusBadge: {
    borderRadius: 12,
    paddingHorizontal: 10,
    paddingVertical: 4,
  },
  statusText: {
    fontSize: 12,
    fontWeight: "600",
    textTransform: "uppercase",
  },
  dateText: {
    fontSize: 12,
    fontWeight: "400",
    color: "#718096",
  },
});
