import { useIsFocused, useNavigation } from "@react-navigation/native";
import moment from "moment";
import React, { useEffect, useState } from "react";
import {
  ActivityIndicator,
  FlatList,
  RefreshControl,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { useDispatch, useSelector } from "react-redux";
import Header from "../../components/Header";
import {
  selectUser,
  setAdvanceMeeting,
  setMeetingQueryKey,
} from "../../redux/userSlice";
import Container from "../../myComponents/Container/Container";
import { getAllMeetingFunc } from "../../redux/action";
import { deleteMeeting } from "../../services/rootApi/meetingApi";
import TitleWithAddDelete from "../../myComponents/TitleWithAddDelete/TitleWithAddDelete";
import { shadow1, shadowPrimaryColor } from "../../const/globalStyle";
import NoDataFound from "../../myComponents/NoDataFound/NoDataFound";
import CustomSnackBar from "../../myComponents/CustomSnackBar/CustomSnackBar";
import DeleteModel from "../../myComponents/DeleteModel";
import SearchBar from "../../myComponents/SearchBar/SearchBar";
import { color } from "../../const/color";
import MeetingListHeading from "../../components/Meeting/MeetingListHeading";
import SkeletonLoadingBooking from "../../components/Booking/SkeletonLoadingBooking";
import SkeletonLoadingMeeting from "../../components/Dashboard/SkeletonLoadingMeeting";
import { roleEnum } from "../../utils/data";
import { askLocationPermission } from "../../utils/location";
import { useGetMeeting } from "../../hooks/useCRMgetQuerry";
import { useQueryClient } from "@tanstack/react-query";
import { debounce } from "../../utils/debounce";
import { myConsole } from "../../hooks/useConsole";
import { queryKeyCRM } from "../../utils/queryKeys";
import { sizes } from "../../const";
import CustomText from "../../myComponents/CustomText/CustomText";
import { LinearGradient } from "expo-linear-gradient";
import SlideFadeIn from "../../utils/animations/SlideFadeIn";

let bgByStatus = {
  reschedule: "#A8C4F5", // soft blue tint
  schedule: "#C9DCFA", // lighter blue for planned
  conducted: "#E4EEFC", // pale bluish-white for done
};

const AllMeetings = () => {
  const queryClient = useQueryClient();
  const { navigate } = useNavigation();
  // const isFocused = useIsFocused();

  const { user, meetingQueryKey } = useSelector(selectUser);

  // const { meeting, advanceMeeting } = useSelector(selectUser);
  const dispatch = useDispatch();
  // let copyMeeting = advanceMeeting !== null ? [...advanceMeeting] : [...meeting]
  // const [filteredMeeting, setFilteredMeeting] = useState(copyMeeting)
  const [selected, setSelected] = useState([]);
  const [modalVisible, setModalVisible] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [snackBar, setSnackBar] = useState({
    visible: false,
    text: "",
    error: false,
  });
  const [searchValue, setSearchValue] = useState("");

  const [showHeaderActions, setShowHeaderActions] = useState(false);
  const flatListRef = React.useRef<FlatList>(null);
  const [focusSearch, setFocusSearch] = useState(false);

  //refresh
  const [refreshing, setRefreshing] = React.useState(false);
  const [debouncedSearch, setDebouncedSearch] = useState("");
  ///ReactQuery
  const {
    data: meetingData,
    isLoading: loading,
    hasNextPage,
    fetchNextPage,
    isFetchingNextPage,
  } = useGetMeeting({
    search: debouncedSearch,
    ...meetingQueryKey,
  });

  //

  const handleSelect = (id) => {
    let temp = [...selected];
    let index = temp.indexOf(id);
    if (index !== -1) {
      temp.splice(index, 1);
    } else {
      temp.push(id);
    }
    setSelected(temp);
  };

  const handleDeleteMeeting = async () => {
    setIsLoading(true);
    try {
      let res = await deleteMeeting(selected);
      // await dispatch(getAllMeetingFunc());
      queryClient.invalidateQueries({
        queryKey: [queryKeyCRM.getMeeting],
      });
      setSelected([]);
      toggleModalClose();
      setSnackBar({
        visible: true,
        text: res?.data,
        error: false,
      });
    } catch (error) {
      setSnackBar({
        visible: true,
        text: err?.response?.data,
        error: false,
      });
    } finally {
      setIsLoading(false);
    }
  };

  const toggleModal = () => {
    setModalVisible(!modalVisible);
  };

  const toggleModalClose = () => {
    setModalVisible(false);
  };

  // useEffect(() => {
  //   if (!!searchValue && copyMeeting !== null) {
  //     let temp = copyMeeting?.filter((el) => {
  //       return el?.lead?.clientName.toLowerCase().includes(searchValue.toLowerCase())
  //         ||
  //         el?.meetings[el?.meetings?.length - 1].status?.toLowerCase().includes(searchValue.toLowerCase())
  //         ||
  //         el?.productPitch?.toLowerCase().includes(searchValue?.toLowerCase())
  //     })
  //     setFilteredMeeting(temp)
  //   }

  // }, [searchValue])

  // const handleFilterTextOnChange = (value) => {
  //   if (value) {
  //     setSearchValue(value)
  //   } else {
  //     setSearchValue('')
  //     setFilteredMeeting(copyMeeting !== null ? [...copyMeeting] : [])
  //   }
  // }

  // useEffect(() => {
  //   if (isFocused) {
  //     // handleFilterTextOnChange('')
  //     setSearchValue('')
  //     setSelected([])
  //     let temp = [...copyMeeting]
  //     temp?.sort((a, b) => Date.parse(b?.updatedAt) - Date.parse(a?.updatedAt))
  //     setFilteredMeeting(temp)
  //   }
  // }, [isFocused, advanceMeeting, meeting])

  useEffect(() => {
    (async () => {
      await askLocationPermission();
    })();
  }, []);

  const debounceSearch = React.useCallback(
    debounce((value) => setDebouncedSearch(value), 500),
    []
  );

  const handleSearchChange = (v) => {
    setSearchValue(v);
    debounceSearch(v);
  };

  const onEndReach = () => {
    if (hasNextPage && !loading && meetingData?.length > 0) {
      fetchNextPage && fetchNextPage();
    }
  };

  const onRefresh = React.useCallback(async () => {
    try {
      setRefreshing(true);
      await queryClient.invalidateQueries({
        queryKey: ["getLead"],
      });
    } catch (e) {
      console.log("refreshGetAllLeave", e);
    } finally {
      setRefreshing(false);
    }
  }, []);

  return (
    <Container>
      <Header
        title={"Meetings"}
        showBackIcon={false}
        isWithAnimation
        showActions={showHeaderActions}
        onPressSearch={() => {
          flatListRef.current?.scrollToOffset({ offset: 0, animated: true });
          setTimeout(() => {
            setFocusSearch((prev) => !prev); // toggles every time
          }, 100);
        }}
        onPressFilter={() => navigate("AdvanceSearch", { type: "meeting" })}
        onPressAdd={() => navigate("AddMeeting")}
      />

      <CustomSnackBar snackbar={snackBar} setSnackbar={setSnackBar} />
      {true ? (
        <View>
          {!showHeaderActions && (
            <TitleWithAddDelete
              isWithAnimation
              arrLength={selected?.length}
              title="Meeting"
              onPressToNavigate={() => navigate("AddMeeting")}
              onPressToDelete={
                user?.role === roleEnum?.sup_admin ? toggleModal : false
              }
              onPressToFilter={() =>
                navigate("AdvanceSearch", { type: "meeting" })
              }
              onCloseSearch={
                meetingQueryKey !== null
                  ? () => dispatch(setMeetingQueryKey(null))
                  : false
              }
            />
          )}

          <FlatList
            data={meetingData}
            ref={flatListRef}
            // data={[]}
            renderItem={({ item, index }) => {
              let status = item?.meetings[item?.meetings?.length - 1]?.status;
              return (
                <MeetingRowItem
                  item={item}
                  index={index}
                  onPress={() =>
                    selected?.length > 0
                      ? handleSelect(item._id)
                      : navigate("MeetingDetails", { item })
                  }
                  selected={selected.indexOf(item?._id) !== -1}
                  onLongPress={
                    user?.role === roleEnum?.sup_admin
                      ? () => handleSelect(item?._id)
                      : undefined
                  }
                  bgColor={bgByStatus[status]}
                />
              );
            }}
            keyExtractor={(item) => item?._id}
            showsVerticalScrollIndicator={true}
            contentContainerStyle={{
              paddingBottom: 300,
            }}
            ListHeaderComponent={
              <>
                <SearchBar
                  onClickCancel={() => {
                    // setSearchValue('')
                    // setFilteredMeeting([...copyMeeting])
                    handleSearchChange("");
                    setFocusSearch(false);
                  }}
                  value={searchValue}
                  isWithAnimation
                  onChangeText={(v) => handleSearchChange(v)}
                  autoFocus={focusSearch}
                />

                <MeetingListHeading />
              </>
            }
            ListHeaderComponentStyle={{ paddingTop: 5 }}
            ListEmptyComponent={
              loading ? (
                <SkeletonLoadingMeeting />
              ) : (
                <NoDataFound style={{ marginTop: sizes.height / 5 }} showTxt />
              )
            }
            onEndReached={onEndReach}
            onEndReachedThreshold={0.5}
            ListFooterComponent={
              isFetchingNextPage && (
                <ActivityIndicator
                  size={"small"}
                  color={color.mainTxtColor}
                  style={{ marginTop: 12 }}
                />
              )
            }
            refreshControl={
              <RefreshControl refreshing={refreshing} onRefresh={onRefresh} />
            }
            onScroll={(e) => {
              const offsetY = e.nativeEvent.contentOffset.y;
              const show = offsetY > 180;
              if (show !== showHeaderActions) {
                setShowHeaderActions(show);
              }
            }}
            scrollEventThrottle={16}
          />
        </View>
      ) : (
        <NoDataFound showTxt />
      )}
      <DeleteModel
        isLoading={isLoading}
        handleDeleteUser={handleDeleteMeeting}
        selectedUser={selected?.email}
        toggleModal={toggleModal}
        modalVisible={modalVisible}
      />
    </Container>
  );
};

const MeetingRowItem = ({
  item,
  onPress,
  onLongPress,
  selected,
  index,
  bgColor = "#fff",
}) => {
  return (
    <SlideFadeIn>
      <TouchableOpacity
        style={[
          styles.mainlistcontainer,
          {
            // backgroundColor: selected ? "rgba(252, 244, 227, 1)" : "#FCFAFA",
            marginTop: index === 0 ? 25 : 12,
            backgroundColor: selected ? "rgba(252, 244, 227, 1)" : bgColor,
          },
        ]}
        activeOpacity={0.5}
        onPress={onPress}
        onLongPress={onLongPress}
      >
        <View style={{ width: "36%" }}>
          <CustomText
            style={{
              color: color.mainTxtColor,
              fontWeight: "600",
              fontSize: 14,
            }}
          >
            {item?.lead?.clientName}
          </CustomText>
          <CustomText
            style={{
              color: color.mainTxtColor,
              fontWeight: "300",
              fontSize: 14,
            }}
          >
            {item?.productPitch}
          </CustomText>
        </View>
        <View style={{ width: "32%", alignItems: "center" }}>
          <CustomText
            style={{
              color: color.mainTxtColor,
              fontWeight: "600",
              fontSize: 14,
              textTransform: "capitalize",
            }}
          >
            {item?.meetings[item?.meetings?.length - 1]?.status}
          </CustomText>
          <CustomText
            style={{
              color: color.strokeColor,
              fontWeight: "300",
              fontSize: 14,
            }}
          >
            <CustomText style={{ color: color.mainTxtColor }}>
              {`${item?.createdBy?.name} (${item?.createdBy?.role
                ?.replace(/_/g, " ")
                .replace(/\b\w/g, (char) => char.toUpperCase())})`}
            </CustomText>
          </CustomText>
        </View>
        <View style={{ width: "32%", alignItems: "flex-end" }}>
          <CustomText
            style={{
              color: color.mainTxtColor,
              fontWeight: "600",
              fontSize: 12,
            }}
          >
            Scheduled
          </CustomText>
          {item?.scheduleDate === "Schedule Date" ? (
            <CustomText
              style={{
                color: color.strokeColor,
                fontWeight: "300",
                fontSize: 12,
              }}
            >
              Schedule Date
            </CustomText>
          ) : (
            <CustomText
              style={{
                color: color.mainTxtColor,
                fontWeight: "400",
                fontSize: 12,
              }}
            >
              {moment(item?.scheduleDate).format("DD/MM/YYYY")}
            </CustomText>
          )}
        </View>
      </TouchableOpacity>
    </SlideFadeIn>
  );
};

const styles = StyleSheet.create({
  divider: {
    borderBottomColor: "#2D67C6",
    width: "100%",
    margin: "auto",
    alignSelf: "center",
    borderBottomWidth: 1,
    marginVertical: -2,
  },
  mainlistcontainer: {
    marginTop: 20,
    borderWidth: 1,
    padding: 12,
    borderRadius: 14,
    borderColor: color.strokeColor,
    flexDirection: "row",
    justifyContent: "space-between",
    marginHorizontal: 20,
    ...shadowPrimaryColor,
  },
});

export default AllMeetings;
