const LeadPool = () => {
  const queryClient = useQueryClient();
  const { user, leadQueryKey } = useSelector(selectUser);
  const isSubSup =
    user?.role === roleEnum.sub_admin || user?.role === roleEnum.sup_admin;
  const { navigate } = useNavigation();
  const [selected, setSelected] = useState([]);
  const [refreshing, setRefreshing] = useState(false);
  const [searchValue, setSearchValue] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const {
    data: leadData,
    isLoading: loading,
    hasNextPage,
    fetchNextPage,
    isFetchingNextPage,
    refetch,
  } = useGetLeadPool({
    search: debouncedSearch,
  });

  const onEndReach = () => {
    if (hasNextPage && !loading && leadData?.length > 0) {
      fetchNextPage && fetchNextPage();
    }
  };

  const onRefresh = async () => {
    try {
      setRefreshing(true);
      await refetch();
    } catch (e) {
      console.log("refreshGetAllLeave", e);
    } finally {
      setRefreshing(false);
    }
  };

  const debounceSearch = useCallback(
    debounce((value) => setDebouncedSearch(value), 500),
    []
  );

  const handleSearchChange = (v) => {
    setSearchValue(v);
    debounceSearch(v);
  };

  const handleSelect = (id) => {
    let temp = [...selected];
    let index = temp.indexOf(id);
    if (index !== -1) {
      temp.splice(index, 1);
    } else {
      temp.push(id);
    }
    setSelected(temp);
  };

  const handleDeleteLeadPool = async () => {
    await deleteLeadsByIds(selected);
    refetch();
    setSelected([]);
  };

  return (
    <>
      <Header title={"Lead Pool"} />
      <Container>
        <TitleWithAddDelete
          arrLength={selected?.length}
          title="Lead"
          onPressToNavigate={() => navigate("AddLeads")}
          onPressToDelete={() =>
            popupModal2.wantDelete({ onConfirm: handleDeleteLeadPool })
          }
        />
        <FlatList
          data={leadData}
          renderItem={({ item, index }) => {
            return (
              <LeadPoolRowItem
                index={index}
                item={item}
                selected={selected?.indexOf(item?._id) !== -1}
                // bgColor={bgByStatus[item?.status]}
                onPress={() => {
                  if (isSubSup) {
                    selected?.length === 0
                      ? navigate("LeadsDetails", { item })
                      : handleSelect(item._id);
                  }
                }}
                // onLongPress={isSubSup ? () => handleSelect(item._id) : undefined}
                onPressClaim={() => {
                  popupModal2.wantDelete({
                    onConfirm: async () => {
                      !!item?._id && (await claimLead(item?._id));
                      refetch();
                    },
                    title: "Do you want to claim!",
                  });
                }}
              />
            );
          }}
          keyExtractor={(item) => item?._id}
          showsVerticalScrollIndicator={true}
          contentContainerStyle={{
            paddingBottom: 100,
          }}
          ListHeaderComponent={
            <View>
              <SearchBar
                onChangeText={(v) => handleSearchChange(v)}
                value={searchValue}
                onClickCancel={() => {
                  handleSearchChange("");
                  // setSearchValue('')
                  // setFilteredData([...copyLead])
                }}
              />
              <LeadPoolHeading />
            </View>
          }
          ListHeaderComponentStyle={{ paddingTop: 5 }}
          ListEmptyComponent={
            loading ? <SkeletonLoadingLead /> : <NoDataFound />
          }
          onEndReached={onEndReach}
          onEndReachedThreshold={0.5}
          ListFooterComponent={
            isFetchingNextPage && (
              <ActivityIndicator
                size={"small"}
                color={color.mainTxtColor}
                style={{ marginTop: 20 }}
              />
            )
          }
          refreshControl={
            <RefreshControl refreshing={refreshing} onRefresh={onRefresh} />
          }
        />
      </Container>
    </>
  );
};

export default LeadPool;

